window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-55f59b4cafdd5229"]={"versions": [{"id": "FIG-55f59b4cafdd5229", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> FODA-basiertes Feature-Modell / Feature-Baum (Feature-Oriented Domain Analysis) zur Variabilitätsmodellierung nach AUTOSAR-Foundation-Standard (<code>AUTOSAR_FO_TR_Features</code>, R24-11).\n</li><li><strong>Architektonischer Kontext:</strong> AUTOSAR Foundation &amp; Adaptive Platform. Das Diagramm definiert die funktionale Dekomposition des Kommunikations-Features <em>Data Distribution Service</em> (DDS) und bestimmt die normativen Abhängigkeiten sowie die optionale Konfigurierbarkeit zugehöriger Sicherheits- und Absicherungs-Erweiterungen im AUTOSAR-Gesamtsystem.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Übergeordnetes Feature (Root / Parent):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00124</code> (<code>DDS</code>): Kern-Feature für datenzentrierte Publish/Subscribe-Kommunikation nach OMG-DDS-Standard (Transport, Discovery, QoS-Policies, Typensystem).\n</li></ul>\n</li><li><strong>Untergeordnete Features (Sub-Features / Children):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00125</code> (<code>DDS_Security</code>): Sicherheitserweiterung (OMG DDS Security Specification: Authentifizierung, Zugriffskontrolle, Verschlüsselung, Logging).\n</li><li><code>FO_TR_FEAT_00126</code> (<code>DDS_E2E</code>): Funktionale Absicherung der Nutzdaten gegen transiente Übertragungsfehler mittels AUTOSAR End-to-End-Protection (E2E-Profile).\n</li></ul>\n</li><li><strong>Beziehungssemantik &amp; Stereotypen:</strong>\n<ul class=\"fig-list\"><li><strong>Optionale Sub-Features:</strong> Durch ungefüllte Kreise (Hollow Circles) an den Kanten der Kindknoten deklariert.\n</li><li><strong>Abhängigkeit:</strong> <code>FO_TR_FEAT_00125</code> und <code>FO_TR_FEAT_00126</code> erfordern zwingend das übergeordnete Basis-Feature <code>FO_TR_FEAT_00124</code>.\n</li><li><strong>Orthogonalität:</strong> Die Kindknoten stehen nicht in Exklusivitätsrelation (XOR/OR); sie können unabhängig voneinander oder kombiniert (0..1 je Feature) zum Basis-DDS-Stack hinzugeschaltet werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend:</strong> Statisches Variabilitäts- und Dekompositionsmodell; keine Darstellung von Steuerflüssen, Zustandsübergängen, Triggern oder Callbacks.\n</li><li><strong>Laufzeit-Wirkung bei Aktivierung:</strong>\n<ul class=\"fig-list\"><li>Bei gleichzeitiger Selektion beider Kind-Features greift im Sender-Pfad zunächst <code>DDS_E2E</code> (Berechnung von CRC/Counter auf Serialisierungsebene), bevor <code>DDS_Security</code> die Payloads oder Submessages über kryptografische Plugins (Crypto-Stack) kapselt und verschlüsselt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Stack- &amp; Plattform-Implementierung (<code>ara::com</code> DDS-Binding):</strong>\n<ul class=\"fig-list\"><li>Eine AUTOSAR-konforme Basis-DDS-Implementierung erfordert lediglich <code>FO_TR_FEAT_00124</code>.\n</li><li><code>FO_TR_FEAT_00125</code> bedingt die Bereitstellung normativer OMG-Security-Plugins und deren Integration in das AUTOSAR Identity and Access Management (IAM) bzw. den Crypto-Stack (<code>ara::crypto</code>).\n</li><li><code>FO_TR_FEAT_00126</code> fordert die Einkapselung von E2E-Transformern/E2E-State-Machines innerhalb des DDS-Serialisierungs-Layers zur Erfüllung von ISO 26262 (ASIL).\n</li></ul>\n</li><li><strong>Systemkonfiguration &amp; ARXML:</strong>\n<ul class=\"fig-list\"><li>Die Merkmale steuern die Generierung und Validierung im Manifest (<code>ServiceInstanceToMachineMapping</code>, <code>DdsProvidedServiceInstance</code>, E2E- und Security-Deployment-Deskriptoren). Fehlt die jeweilige Konfiguration, darf der Codegenerator die entsprechenden Header/Libraries nicht einbinden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-d97f8cb7660d4d53", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> FODA-basiertes Feature-Modell / Feature-Baum (Feature-Oriented Domain Analysis) zur Variabilitätsmodellierung nach AUTOSAR-Foundation-Standard (<code>AUTOSAR_FO_TR_Features</code>, R24-11).\n</li><li><strong>Architektonischer Kontext:</strong> AUTOSAR Foundation &amp; Adaptive Platform. Das Diagramm definiert die funktionale Dekomposition des Kommunikations-Features <em>Data Distribution Service</em> (DDS) und bestimmt die normativen Abhängigkeiten sowie die optionale Konfigurierbarkeit zugehöriger Sicherheits- und Absicherungs-Erweiterungen im AUTOSAR-Gesamtsystem.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Übergeordnetes Feature (Root / Parent):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00124</code> (<code>DDS</code>): Kern-Feature für datenzentrierte Publish/Subscribe-Kommunikation nach OMG-DDS-Standard (Transport, Discovery, QoS-Policies, Typensystem).\n</li></ul>\n</li><li><strong>Untergeordnete Features (Sub-Features / Children):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00125</code> (<code>DDS_Security</code>): Sicherheitserweiterung (OMG DDS Security Specification: Authentifizierung, Zugriffskontrolle, Verschlüsselung, Logging).\n</li><li><code>FO_TR_FEAT_00126</code> (<code>DDS_E2E</code>): Funktionale Absicherung der Nutzdaten gegen transiente Übertragungsfehler mittels AUTOSAR End-to-End-Protection (E2E-Profile).\n</li></ul>\n</li><li><strong>Beziehungssemantik &amp; Stereotypen:</strong>\n<ul class=\"fig-list\"><li><strong>Optionale Sub-Features:</strong> Durch ungefüllte Kreise (Hollow Circles) an den Kanten der Kindknoten deklariert.\n</li><li><strong>Abhängigkeit:</strong> <code>FO_TR_FEAT_00125</code> und <code>FO_TR_FEAT_00126</code> erfordern zwingend das übergeordnete Basis-Feature <code>FO_TR_FEAT_00124</code>.\n</li><li><strong>Orthogonalität:</strong> Die Kindknoten stehen nicht in Exklusivitätsrelation (XOR/OR); sie können unabhängig voneinander oder kombiniert (0..1 je Feature) zum Basis-DDS-Stack hinzugeschaltet werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend:</strong> Statisches Variabilitäts- und Dekompositionsmodell; keine Darstellung von Steuerflüssen, Zustandsübergängen, Triggern oder Callbacks.\n</li><li><strong>Laufzeit-Wirkung bei Aktivierung:</strong>\n<ul class=\"fig-list\"><li>Bei gleichzeitiger Selektion beider Kind-Features greift im Sender-Pfad zunächst <code>DDS_E2E</code> (Berechnung von CRC/Counter auf Serialisierungsebene), bevor <code>DDS_Security</code> die Payloads oder Submessages über kryptografische Plugins (Crypto-Stack) kapselt und verschlüsselt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Stack- &amp; Plattform-Implementierung (<code>ara::com</code> DDS-Binding):</strong>\n<ul class=\"fig-list\"><li>Eine AUTOSAR-konforme Basis-DDS-Implementierung erfordert lediglich <code>FO_TR_FEAT_00124</code>.\n</li><li><code>FO_TR_FEAT_00125</code> bedingt die Bereitstellung normativer OMG-Security-Plugins und deren Integration in das AUTOSAR Identity and Access Management (IAM) bzw. den Crypto-Stack (<code>ara::crypto</code>).\n</li><li><code>FO_TR_FEAT_00126</code> fordert die Einkapselung von E2E-Transformern/E2E-State-Machines innerhalb des DDS-Serialisierungs-Layers zur Erfüllung von ISO 26262 (ASIL).\n</li></ul>\n</li><li><strong>Systemkonfiguration &amp; ARXML:</strong>\n<ul class=\"fig-list\"><li>Die Merkmale steuern die Generierung und Validierung im Manifest (<code>ServiceInstanceToMachineMapping</code>, <code>DdsProvidedServiceInstance</code>, E2E- und Security-Deployment-Deskriptoren). Fehlt die jeweilige Konfiguration, darf der Codegenerator die entsprechenden Header/Libraries nicht einbinden.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-55f59b4cafdd5229", "to": "FIG-d97f8cb7660d4d53", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
